def certify_existing_members(apps, schema_editor):
    """Members who could log in before e-mail certification existed stay able to: their address
    counts as certified on the day they joined, so turning cf_use_email_certify on later does not
    lock everyone out. open_profile takes the register_form.php default (checked) from the field."""
